// ─── PRACTICE PAGE ───────────────────────────────────────────────────────────

// buildOptions is defined outside to avoid temporal dead zone issues
function buildOptions(sit, p, lang) {
  if (sit.community && (Array.isArray(sit.optionsEs) || Array.isArray(sit.optionsEn) || Array.isArray(sit.options))) {
    const opts = (lang === "es" ? sit.optionsEs : sit.optionsEn) || sit.optionsEs || sit.optionsEn || sit.options;
    const correctExplain = (lang === "es" ? sit.correctExplainEs : sit.correctExplainEn) || sit.correctExplainEs || sit.correctExplainEn || sit.correctExplain || "";
    const wrongExplain = (lang === "es" ? sit.wrongExplainEs : sit.wrongExplainEn) || sit.wrongExplainEs || sit.wrongExplainEn || sit.wrongExplain || "";
    return opts.map((opt, idx) => ({
      id: "opt" + idx,
      label: opt,
      correct: idx === sit.correctIndex,
      explanation: idx === sit.correctIndex ? correctExplain : (wrongExplain || correctExplain),
    })).sort(() => Math.random() - 0.5);
  }

  const correctExp = lang === "es" ? sit.es : sit.en;

  if (sit.type === "3bet") {
    // ── Defending vs 3-bet (héroe abrió, rival 3-beteó) ─────────────────────
    if (sit.defending3bet) {
      const fourBetLabel = lang === "es" ? "4-Bet" : "4-Bet";
      const callLabel    = lang === "es" ? "Pagar (call)" : "Call";
      if (sit.open) {
        // correct = 4-bet (value or bluff)
        return [
          { id:"correct", label: fourBetLabel, correct: true,  explanation: correctExp },
          { id:"call",    label: callLabel,     correct: false, explanation: lang==="es" ? "Pagar el 3-bet con esta mano cede valor y posición — el 4-bet es la línea superior." : "Calling the 3-bet with this hand gives up value and position — 4-betting is the superior line." },
          { id:"fold",    label: p.optFold,     correct: false, explanation: lang==="es" ? "Foldear aquí es demasiado pasivo — esta mano merece el 4-bet." : "Folding here is too passive — this hand deserves the 4-bet." },
        ].sort(() => Math.random() - 0.5);
      } else if (sit.size === "call") {
        // correct = call the 3-bet (IP, good hand)
        return [
          { id:"correct", label: callLabel,     correct: true,  explanation: correctExp },
          { id:"4bet",    label: fourBetLabel,   correct: false, explanation: lang==="es" ? "El 4-bet con esta mano es demasiado fino — pagar y ver un flop en posición es superior." : "4-betting with this hand is too thin — calling and seeing a flop in position is superior." },
          { id:"fold",    label: p.optFold,      correct: false, explanation: lang==="es" ? "Esta mano tiene suficiente equity e implied odds para pagar el 3-bet en posición." : "This hand has enough equity and implied odds to call the 3-bet in position." },
        ].sort(() => Math.random() - 0.5);
      } else {
        // correct = fold the 3-bet (OOP, dominated, etc.)
        return [
          { id:"correct", label: p.optFold,     correct: true,  explanation: correctExp },
          { id:"4bet",    label: fourBetLabel,   correct: false, explanation: lang==="es" ? "El 4-bet con esta mano no tiene suficiente valor ni bloqueadores para ser rentable aquí." : "4-betting with this hand doesn't have enough value or blockers to be profitable here." },
          { id:"call",    label: callLabel,      correct: false, explanation: lang==="es" ? "Pagar el 3-bet con esta mano OOP o dominada tiene EV negativo." : "Calling the 3-bet with this hand OOP or dominated has negative EV." },
        ].sort(() => Math.random() - 0.5);
      }
    }
    // ── Standard 3-bet / squeeze ──────────────────────────────────────────────
    const raiseLabel = sit.facing4bet ? (lang==="es" ? "5-Bet (all-in)" : "5-Bet (all-in)") : "3-Bet";
    const callLabel = lang === "es" ? "Pagar (call)" : "Call";
    if (sit.open) {
      return [
        { id:"correct", label: raiseLabel, correct: true,  explanation: correctExp },
        { id:"call",    label: callLabel,  correct: false, explanation: sit.facing4bet
            ? (lang==="es" ? "Pagar aquí cede demasiado valor — esta mano es lo bastante fuerte para ir a por todo (5-bet all-in)." : "Calling here gives up too much value — this hand is strong enough to go all-in (5-bet).")
            : (lang==="es" ? "Pagar aquí cede demasiado valor o te deja en una situación incómoda fuera de posición — el 3-bet es superior." : "Calling here gives up too much value or leaves you in an awkward out-of-position spot — 3-betting is better.") },
        { id:"fold",    label: p.optFold,  correct: false, explanation: sit.facing4bet
            ? (lang==="es" ? "Esta mano tiene demasiado valor para foldear aquí — foldear cede una mano ganadora con mucha frecuencia." : "This hand has too much value to fold here — folding gives up a winning hand far too often.")
            : (lang==="es" ? "Esta mano tiene suficiente valor (o bloqueadores) para 3-betear — foldear es demasiado pasivo." : "This hand has enough value (or blockers) to 3-bet — folding is too passive.") },
        { id:"limp",    label: p.optLimp,  correct: false, explanation: p.wrongLimpExp },
      ].sort(() => Math.random() - 0.5);
    } else if (sit.size === "call") {
      return [
        { id:"correct", label: callLabel,  correct: true,  explanation: correctExp },
        { id:"raise",   label: raiseLabel, correct: false, explanation: sit.facing4bet
            ? (lang==="es" ? "Un 5-bet all-in aquí es demasiado — pagar el 4-bet y ver el flop es la línea más sólida con esta mano." : "A 5-bet all-in here is too much — calling the 4-bet and seeing a flop is the soundest line with this hand.")
            : (lang==="es" ? "Un 3-bet aquí es demasiado fino o te expone a un 4-bet en mala posición — pagar es la línea más sólida." : "A 3-bet here is too thin or exposes you to a 4-bet in a bad spot — calling is the soundest line.") },
        { id:"fold",    label: p.optFold,  correct: false, explanation: lang==="es" ? "Esta mano sí es lo bastante buena para pagar aquí." : "This hand is good enough to call here." },
        { id:"limp",    label: p.optLimp,  correct: false, explanation: p.wrongLimpExp },
      ].sort(() => Math.random() - 0.5);
    } else {
      return [
        { id:"correct", label: p.optFold,  correct: true,  explanation: correctExp },
        { id:"raise",   label: raiseLabel, correct: false, explanation: sit.facing4bet
            ? (lang==="es" ? "Esta mano no tiene el valor ni los bloqueadores necesarios para un 5-bet all-in rentable aquí." : "This hand doesn't have the value or blockers needed for a profitable 5-bet all-in here.")
            : (lang==="es" ? "Esta mano no tiene el valor ni los bloqueadores necesarios para un 3-bet rentable aquí." : "This hand doesn't have the value or blockers needed for a profitable 3-bet here.") },
        { id:"call",    label: callLabel,  correct: false, explanation: sit.facing4bet
            ? (lang==="es" ? "Pagar aquí te mete en un bote enorme con una mano que no aguanta bien el rango de 4-bet del rival." : "Calling here puts you in a huge pot with a hand that doesn't hold up well against villain's 4-bet range.")
            : (lang==="es" ? "Pagar aquí te mete en un spot -EV jugando fuera de posición o multiway con una mano débil." : "Calling here puts you in a -EV spot playing out of position or multiway with a weak hand.") },
        { id:"limp",    label: p.optLimp,  correct: false, explanation: p.wrongLimpExp },
      ].sort(() => Math.random() - 0.5);
    }
  }

  if (sit.type === "cbet") {
    const correctExp = lang === "es" ? sit.es : sit.en;
    if (sit.open) {
      // correct size + check + two wrong sizes (exclude duplicate of correct)
      const allSizes = [
        { id:"small", label: p.optCbetSmall },
        { id:"large", label: p.optCbetLarge },
        { id:"pot",   label: p.optCbetPot   },
      ];
      const correctOpt = { id:"correct", label: allSizes.find(s => s.id === sit.size).label, correct: true,  explanation: correctExp };
      const wrongSizes = allSizes.filter(s => s.id !== sit.size).map(s => ({ id:"w_"+s.id, label: s.label, correct: false, explanation: p.wrongCbetSizeExp }));
      return [
        correctOpt,
        { id:"check", label: p.optCheck, correct: false, explanation: p.wrongCheckWhenBetExp },
        wrongSizes[0],
        wrongSizes[1],
      ].sort(() => Math.random() - 0.5);
    } else {
      return [
        { id:"correct", label: p.optCheck,      correct: true,  explanation: correctExp },
        { id:"wsmall",  label: p.optCbetSmall,  correct: false, explanation: p.wrongBetWhenCheckExp },
        { id:"wlarge",  label: p.optCbetLarge,  correct: false, explanation: p.wrongBetWhenCheckExp },
        { id:"wpot",    label: p.optCbetPot,    correct: false, explanation: p.wrongBetWhenCheckExp },
      ].sort(() => Math.random() - 0.5);
    }
  }

  if (sit.type === "call") {
    if (sit.open) {
      return [
        { id:"correct", label: lang==="es" ? "Pagar" : "Call",   correct:true,  explanation:correctExp },
        { id:"fold",    label: p.optFold,                        correct:false, explanation: lang==="es" ? "Esta mano sí es pago rentable en esta situación." : "This hand is a profitable call in this situation." },
        { id:"wsize",   label: lang==="es" ? "3-bet" : "3-bet",  correct:false, explanation: lang==="es" ? "Pagar es la línea más correcta aquí, no 3-bet." : "Calling is the most correct line here, not 3-betting." },
        { id:"limp",    label: p.optLimp,                        correct:false, explanation: lang==="es" ? "No se limpa — o pagas la apertura correctamente o foldeas." : "Don't limp — either call the open correctly or fold." },
      ].sort(() => Math.random() - 0.5);
    } else {
      return [
        { id:"correct", label: p.optFold,                        correct:true,  explanation:correctExp },
        { id:"call",    label: lang==="es" ? "Pagar" : "Call",   correct:false, explanation: lang==="es" ? "Esta mano no es pago rentable aquí." : "This hand is not a profitable call here." },
        { id:"limp",    label: p.optLimp,                        correct:false, explanation: p.wrongLimpExp },
        { id:"w3bet",   label: lang==="es" ? "3-bet" : "3-bet",  correct:false, explanation: lang==="es" ? "Foldear es la mejor opción aquí." : "Folding is the best option here." },
      ].sort(() => Math.random() - 0.5);
    }
  }

  if (sit.type === "vbet") {
    // ── Bluff barrel decision (bluff:true) ────────────────────────────────────
    if (sit.bluff) {
      const betLabel  = lang === "es" ? "Apostar (farol)" : "Bet (bluff)";
      const checkLabel = lang === "es" ? "Checkear (ceder)" : "Check (give up)";
      if (sit.open) {
        // correct = fire the bluff barrel
        return [
          { id:"correct", label: betLabel,   correct: true,  explanation: correctExp },
          { id:"check",   label: checkLabel, correct: false, explanation: lang==="es" ? "Checkear aquí cede demasiado valor — tienes suficiente equity y fold equity para disparar el barrel." : "Checking here gives up too much — you have enough equity and fold equity to fire the barrel." },
        ].sort(() => Math.random() - 0.5);
      } else {
        // correct = check / give up
        return [
          { id:"correct", label: checkLabel, correct: true,  explanation: correctExp },
          { id:"bet",     label: betLabel,   correct: false, explanation: lang==="es" ? "Apostar aquí como farol no tiene suficiente fold equity o la mano tiene showdown value — checkear es la línea correcta." : "Betting here as a bluff doesn't have enough fold equity or the hand has showdown value — checking is the correct line." },
        ].sort(() => Math.random() - 0.5);
      }
    }
    // ── Standard value bet ────────────────────────────────────────────────────
    if (sit.open) {
      const allSizes = [
        { id:"small",  label: p.optCbetSmall  },
        { id:"medium", label: p.optVbetMedium },
        { id:"large",  label: p.optCbetLarge  },
        { id:"pot",    label: p.optCbetPot    },
      ];
      const correctOpt = { id:"correct", label: allSizes.find(s => s.id === sit.size).label, correct: true,  explanation: correctExp };
      const wrongSizes = allSizes.filter(s => s.id !== sit.size).map(s => ({ id:"w_"+s.id, label: s.label, correct: false, explanation: p.wrongCbetSizeExp }));
      return [
        correctOpt,
        { id:"check", label: p.optCheck, correct: false, explanation: p.wrongCheckWhenBetExp },
        wrongSizes[0],
        wrongSizes[1],
      ].sort(() => Math.random() - 0.5);
    } else {
      return [
        { id:"correct", label: p.optCheck,      correct: true,  explanation: correctExp },
        { id:"wsmall",  label: p.optCbetSmall,  correct: false, explanation: p.wrongBetWhenCheckExp },
        { id:"wlarge",  label: p.optCbetLarge,  correct: false, explanation: p.wrongBetWhenCheckExp },
        { id:"wpot",    label: p.optCbetPot,    correct: false, explanation: p.wrongBetWhenCheckExp },
      ].sort(() => Math.random() - 0.5);
    }
  }

  if (sit.type === "iso") {
    const isoLabel   = sit.limpers === 2 ? p.optIso5 : p.optIso4;
    const wrongLabel = sit.limpers === 2 ? p.optIso6 : p.optIso8;
    if (sit.open) {
      return [
        { id:"correct", label: isoLabel,         correct: true,  explanation: correctExp },
        { id:"fold",    label: p.optFold,         correct: false, explanation: p.wrongIsoOpenExp },
        { id:"limp",    label: p.optLimpBehind,   correct: false, explanation: p.wrongLimpBehindExp },
        { id:"wsize",   label: wrongLabel,         correct: false, explanation: p.wrongSizeExp },
      ].sort(() => Math.random() - 0.5);
    } else {
      return [
        { id:"correct", label: p.optFold,         correct: true,  explanation: correctExp },
        { id:"wiso",    label: isoLabel,           correct: false, explanation: p.wrongIsoFoldExp },
        { id:"limp",    label: p.optLimpBehind,   correct: false, explanation: p.wrongLimpBehindExp },
        { id:"wsize",   label: wrongLabel,         correct: false, explanation: p.wrongSizeExp },
      ].sort(() => Math.random() - 0.5);
    }
  }

  if (sit.type === "facing") {
    const callLabel  = lang === "es" ? "Pagar (call)" : "Call";
    const raiseLabel = lang === "es" ? "Resubir (raise)" : "Raise";
    const isAllIn = sit.ctx === "facing_allin";
    const checkOpt = { id:"check", label: lang==="es" ? "Checkear" : "Check", correct: false, explanation: lang==="es" ? "El rival ya apostó — no puedes checkear. Debes pagar o foldear." : "Villain already bet — you can't check. You must call or fold." };
    const raiseOptOpen = { id:"raise", label: raiseLabel, correct: false, explanation: lang==="es" ? "Resubir aquí no tiene sentido estratégico. La decisión es call o fold." : "Raising here makes no strategic sense. The decision is call or fold." };
    const raiseOptClosed = { id:"raise", label: raiseLabel, correct: false, explanation: lang==="es" ? "Bluffear con un raise aquí no tiene sentido — el rango del rival está cargado de valor." : "Bluff-raising here makes no sense — villain's range is value-heavy." };
    if (sit.open) {
      return [
        { id:"correct", label: callLabel,  correct: true,  explanation: correctExp },
        { id:"fold",    label: p.optFold,  correct: false, explanation: lang==="es" ? "Con la equidad que tienes vs el rango del rival, pagar tiene más EV que foldear." : "With your equity vs villain's range, calling has more EV than folding." },
        ...(isAllIn ? [] : [raiseOptOpen]),
        checkOpt,
      ].sort(() => Math.random() - 0.5);
    } else {
      return [
        { id:"correct", label: p.optFold,  correct: true,  explanation: correctExp },
        { id:"call",    label: callLabel,   correct: false, explanation: lang==="es" ? "No tienes la equidad necesaria para justificar el call contra el rango probable del rival." : "You don't have the required equity to justify the call vs villain's likely range." },
        ...(isAllIn ? [] : [raiseOptClosed]),
        checkOpt,
      ].sort(() => Math.random() - 0.5);
    }
  }

  // Standard open situation
  const correctLabel = sit.open ? (sit.size === "3x" ? p.optOpen3 : p.optOpen25) : p.optFold;
  if (!sit.open) {
    return [
      { id:"correct", label: p.optFold,   correct: true,  explanation: correctExp },
      { id:"wopen3",  label: p.optOpen3,  correct: false, explanation: p.wrongOpenExp },
      { id:"wopen25", label: p.optOpen25, correct: false, explanation: p.wrongOpenExp },
      { id:"limp",    label: p.optLimp,   correct: false, explanation: p.wrongLimpExp },
    ].sort(() => Math.random() - 0.5);
  }
  return [
    { id:"correct", label: correctLabel,                                  correct: true,  explanation: correctExp },
    { id:"fold",    label: p.optFold,                                     correct: false, explanation: p.wrongFoldExp },
    { id:"wsize",   label: sit.size === "3x" ? p.optOpen2 : p.optOpen4,  correct: false, explanation: p.wrongSizeExp },
    { id:"limp",    label: p.optLimp,                                     correct: false, explanation: p.wrongLimpExp },
  ].sort(() => Math.random() - 0.5);
}

// Genera la lista de "jugadas correctas" posibles para una situación, según su tipo.
// Cada opción es { open, size, label }. Usado por EditProposalModal para que el usuario
// elija cuál cree que debería ser la jugada correcta.
function correctActionOptions(sit, p, lang) {
  if (sit.type === "3bet") {
    return [
      { open: true,  size: "value", label: sit.facing4bet ? "5-Bet (all-in)" : "3-Bet" },
      { open: false, size: "call",  label: p.actionCall },
      { open: false, size: null,    label: p.optFold },
    ];
  }
  if (sit.type === "cbet" || sit.type === "vbet") {
    const opts = [
      { open: false, size: null, label: p.optCheck },
      { open: true,  size: "small", label: p.optCbetSmall },
    ];
    if (sit.type === "vbet") opts.push({ open: true, size: "medium", label: p.optVbetMedium });
    opts.push({ open: true, size: "large", label: p.optCbetLarge });
    opts.push({ open: true, size: "pot", label: p.optCbetPot });
    return opts;
  }
  if (sit.type === "iso") {
    const isoLabel = sit.limpers === 2 ? p.optIso5 : p.optIso4;
    return [
      { open: true,  size: null, label: isoLabel },
      { open: false, size: null, label: p.optFold },
    ];
  }
  if (sit.type === "call" || sit.type === "facing") {
    return [
      { open: true,  size: null, label: p.actionCall },
      { open: false, size: null, label: p.optFold },
    ];
  }
  // open type (RFI)
  const openLabel = sit.size === "3x" ? p.optOpen3 : p.optOpen25;
  return [
    { open: true,  size: null, label: openLabel },
    { open: false, size: null, label: p.optFold },
  ];
}

// Aplica un override aprobado por la comunidad (o editado por el admin) sobre una situación.
// `overrides` es un mapa { "type_id": { open, size, es, en, hand, board, pos, callPos, ctx,
// descEs, descEn, players, street, limpers, facing4bet } }. Las propuestas de la comunidad
// solo suelen rellenar open/size/es/en; el editor de admin puede ajustar cualquier campo.
function applyOverride(sit, overrides) {
  if (!overrides || !sit) return sit;
  const ov = overrides[`${sit.type}_${sit.id}`];
  if (!ov) return sit;
  const merged = { ...sit };
  const FIELDS = ["open","size","es","en","hand","board","pos","callPos","ctx","descEs","descEn","players","street","limpers","facing4bet"];
  FIELDS.forEach((f) => {
    if (ov[f] !== null && ov[f] !== undefined) merged[f] = ov[f];
  });
  return merged;
}


